#include <stdio.h>
#include <string.h>

int isPalindrome(const char *s) {
    int l = 0, r = strlen(s) - 1;
    while (l < r) {
        if (s[l++] != s[r--]) return 0;
    }
    return 1;
}

int main(void) {
    printf("racecar: %s\n", isPalindrome("racecar") ? "YES" : "NO");
    printf("seed: %s\n", isPalindrome("seed") ? "YES" : "NO");
    return 0;
}

